import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    w = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            w[i][j] = int(next(it))

    INF = -10**18
    f = [[INF] * (n + 1) for _ in range(n + 1)]
    f[1][1] = w[1][1]

    # 四种跳跃的 (行变化, 列变化)
    moves = [(2, 1), (-2, 1), (1, 2), (-1, 2)]

    for j in range(2, n + 1):          # 按列更新
        for i in range(1, n + 1):      # 遍历所有行
            for dx, dy in moves:       # 枚举来源格子
                pi, pj = i - dx, j - dy
                if 1 <= pi <= n and 1 <= pj <= n:
                    if f[pi][pj] != INF:
                        f[i][j] = max(f[i][j], f[pi][pj] + w[i][j])

    ans = 0
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if f[i][j] > ans:
                ans = f[i][j]
    print(ans)

if __name__ == "__main__":
    solve()
```

