```java
import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        int[][] w = new int[n+1][n+1];
        for (int i = 1; i <= n; i++) {
            String[] parts = br.readLine().trim().split("\\s+");
            for (int j = 1; j <= n; j++) {
                w[i][j] = Integer.parseInt(parts[j-1]);
            }
        }
        long INF = Long.MIN_VALUE / 2;
        long[][] f = new long[n+1][n+1];
        for (long[] row : f) Arrays.fill(row, INF);
        f[1][1] = w[1][1];
        int[][] moves = {{2,1}, {-2,1}, {1,2}, {-1,2}};
        for (int j = 2; j <= n; j++) {
            for (int i = 1; i <= n; i++) {
                for (int[] m : moves) {
                    int pi = i - m[0];
                    int pj = j - m[1];
                    if (pi >= 1 && pi <= n && pj >= 1 && pj <= n) {
                        if (f[pi][pj] != INF) {
                            f[i][j] = Math.max(f[i][j], f[pi][pj] + w[i][j]);
                        }
                    }
                }
            }
        }
        long ans = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (f[i][j] > ans) ans = f[i][j];
            }
        }
        System.out.println(ans);
    }
}
